"""Validation rules.

Each rule is built from a spec dict, e.g.::

    {"check": "null_fraction", "col": "phone", "max_fraction": 0.1,
     "severity": "warn"}

``severity`` defaults to ``"error"`` when omitted.
"""

from __future__ import annotations


class Rule:
    """Base class for threshold rules."""

    def __init__(self, check: str, col: str, severity: str | None = None):
        if severity is None:
            severity = "error"
        if severity not in ("error", "warn"):
            raise ValueError(f"invalid severity: {severity!r}")
        self.check = check
        self.col = col
        self.severity = severity

    def observe(self, values: list) -> float:
        raise NotImplementedError

    def passes(self, observed: float) -> bool:
        raise NotImplementedError

    def spec(self) -> dict:
        """Threshold parameters to embed in the report."""
        raise NotImplementedError

    def evaluate(self, values: list) -> dict:
        observed = round(float(self.observe(values)), 3)
        return {
            "check": self.check,
            "col": self.col,
            **self.spec(),
            "severity": self.severity,
            "observed": observed,
            "status": "pass" if self.passes(observed) else "fail",
        }


class NullFractionRule(Rule):
    """Passes when the fraction of null (empty/missing) values is at most
    ``max_fraction``."""

    def __init__(self, col: str, max_fraction: float, severity: str | None = None):
        super().__init__("null_fraction", col, severity)
        self.max_fraction = float(max_fraction)

    def observe(self, values: list) -> float:
        if not values:
            return 0.0
        nulls = sum(1 for v in values if v is None or v == "")
        return nulls / len(values)

    def passes(self, observed: float) -> bool:
        return observed <= self.max_fraction

    def spec(self) -> dict:
        return {"max_fraction": self.max_fraction}


class MinRule(Rule):
    """Passes when every non-null value in the column is >= ``min``."""

    def __init__(self, col: str, min_value: float, severity: str | None = None):
        super().__init__("min", col, severity)
        self.min_value = float(min_value)

    def observe(self, values: list) -> float:
        present = [float(v) for v in values if v is not None and v != ""]
        if not present:
            return float("inf")
        return min(present)

    def passes(self, observed: float) -> bool:
        return observed >= self.min_value

    def spec(self) -> dict:
        return {"min": self.min_value}


_CHECKS = {
    "null_fraction": NullFractionRule,
    "min": MinRule,
}


def build_rule(spec: dict) -> Rule:
    spec = dict(spec)
    check = spec.pop("check")
    if check not in _CHECKS:
        raise ValueError(f"unknown check: {check!r}")
    return _CHECKS[check](**spec)

