def __init__(self, col: str, **kwargs):
    # spec uses the key "min" (a dict key, so not shadowing the builtin)
    super().__init__("min", col, kwargs.pop("severity", None))
    self.min_value = float(kwargs.pop("min"))
    if kwargs:
        raise TypeError(f"unexpected rule params: {sorted(kwargs)}")
